styles:
:root { color-scheme: light; }
* { box-sizing: border-box; }
html, body { margin:0; min-height:100%; }
body { background:#e5e7eb; font-family:Arial,sans-serif; }
.sheet { position:relative; box-sizing:content-box; width:612pt; height:792pt; margin:24px auto; background:white; box-shadow:0 4px 25px rgba(0,0,0,.18); overflow:hidden; }
.sheet svg.artwork, .sheet svg.footer-patch, .sheet svg.ornaments {display:block; width:100%; height:100%; position:absolute;top:0;left:0;}
.txt { position:absolute; white-space:pre; line-height:1; color:#000; transform-origin:0 0; }
.selectable .txt {color:transparent; user-select:text; }
.selectable .txt::selection {color:transparent;background:rgba(35,128,250,.35);}
@media print {
  @page {size:letter; margin:0;}
  html,body {width:612pt; height:792pt; background:white;}
  .sheet {margin:0;box-shadow:none;break-after:avoid;}
}

.ornaments {pointer-events:none;}
@media(max-width:850px) {body {overflow-x:auto;}}
